        case .if_(let cond, let then, let els):
          visitExpr(cond, params); visitStmt(then, params)
          if let els { visitStmt(els, params) }
        case .while_(let cond, let body):
          visitExpr(cond, params); visitStmt(body, params)
        case .doWhile(let body, let cond):
          visitStmt(body, params); visitExpr(cond, params)
        case .for_(let initS, let cond, let post, let body):
